const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>n<1024?n+' B':n<1048576?(n/1024).toFixed(1)+' KB':(n/1048576).toFixed(1)+' MB';
const labels={todo:'To make',doing:'In the making',done:'Made it'};
const day=()=>new Date().toLocaleDateString('en-CA');
let drawing=null,transfers=null,fileRender=0,fileSignature="";
let awareness=null,rich=null,noteMode='write';
let rooms=[],room=null,doc=null,save=null,net=null,bc=null,undo=null,view='board',noteId=null,renderQueued=false,toastTimer,config={},receivingFiles=new Map(),lastNoteCaret=null,dialogFocus;
let prefs={name:'Maker',theme:'light',advanced:false,chat:true,nav:window.innerWidth>=760};
try{prefs={...prefs,...JSON.parse(localStorage.getItem('peerbench-prefs')||'{}')};if(innerWidth<760)prefs.nav=false;}catch{}
function setPrefs(){localStorage.setItem('peerbench-prefs',JSON.stringify(prefs));applyPrefs();}
function applyPrefs(){document.documentElement.dataset.theme=['light','dark','contrast'].includes(prefs.theme)?prefs.theme:'light';document.body.classList.toggle('nav-collapsed',!prefs.nav);$('#work-area').classList.toggle('chat-collapsed',!prefs.chat);$('#toggle-chat').setAttribute('aria-expanded',String(prefs.chat));if(prefs.chatWidth&&innerWidth>1050)$('#chat-pane').style.width=Math.max(230,Math.min(450,prefs.chatWidth))+'px';else $('#chat-pane').style.width='';$('#profile-name').textContent=prefs.name||'Maker';$('#avatar').textContent=(prefs.name||'M')[0].toUpperCase();}
function toast(text){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,5000);}
function error(e){console.error(e);toast(e.message||String(e));const target=$('#dialog-error');if(target)target.textContent=e.message||String(e);}
function action(fn){return e=>{try{Promise.resolve(fn(e)).catch(error);}catch(e){error(e);}};}
function download(name,data,type='application/json'){const url=URL.createObjectURL(data instanceof Blob?data:new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
const safeName=x=>String(x||'room').replace(/[^a-z0-9._-]+/gi,'-').slice(0,80);
function modal(title,body){dialogFocus=document.activeElement;$('#dialog-content').innerHTML=`<div class="dialog-header"><h2>${esc(title)}</h2><button class="icon-button" id="close-dialog" aria-label="Close dialog">×</button></div><div class="dialog-body">${body}<p id="dialog-error" class="error-message" role="alert"></p></div>`;$('#close-dialog').onclick=closeModal;if(!$('#dialog').open)$('#dialog').showModal();}
function closeModal(){$('#dialog').close();dialogFocus?.focus?.();}
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=$('#dialog').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
function mapRows(name){return [...doc.getMap(name)].filter(([,x])=>name==='tasks'||name==='notes'?x instanceof Y.Map&& !x.get('deleted'):x&&!x.deleted);}
function scheduleRender(){if(renderQueued)return;renderQueued=true;queueMicrotask(()=>{renderQueued=false;if(doc)renderRoom();});}
function renderRooms(){$('#room-list').innerHTML=rooms.map(r=>`<button class="room-link ${r.id===room?.id?'active':''}" data-room="${r.id}" ${r.id===room?.id?'aria-current="page"':''}><span class="room-dot">▦</span><span>${esc(r.name)}${r.archived?' · archived':''}</span></button>`).join('')||'<div class="muted" style="padding:10px">Your next project starts here.</div>';$$('[data-room]').forEach(b=>b.onclick=action(()=>openRoom(b.dataset.room)));}
function status(state,e){const el=$('#save-status');el.classList.toggle('error',state==='error');el.textContent=({saving:'◐ Saving locally',saved:'● Saved on this device',error:'! Local save failed'})[state]||'● Ready';if(e)toast('Local saving failed. Export a backup now. '+e.message);}
async function openRoom(id){if(save)await save.settled();transfers?.destroy();transfers=null;drawing?.destroy();drawing=null;rich?.destroy();rich=null;awareness?.destroy();awareness=null;net?.destroy();save?.destroy();bc?.close();undo?.destroy();undo=null;doc?.destroy();receivingFiles.clear();net=null;room=rooms.find(r=>r.id===id);if(!room)return;doc=await S.loadDoc(id);transfers=new Transfers(room,doc,{network:()=>net,name:()=>prefs.name,changed:scheduleRender,toast});await transfers.restore();awareness=new Awareness(doc);awareness.setLocalStateField('user',{name:prefs.name,color:'#355ccc'});save=S.persistence(id,doc,status);view='board';noteId=null;doc.on('beforeTransaction',tr=>{if(tr.origin==='ui')return;const body=$('#note-body');const text=doc.getMap('notes').get(noteId)?.get('body');if(body&&document.activeElement===body&&text instanceof Y.Text){lastNoteCaret={a:Y.createRelativePositionFromTypeIndex(text,body.selectionStart),b:Y.createRelativePositionFromTypeIndex(text,body.selectionEnd)};}});doc.on('update',(u,origin)=>{scheduleRender();if(origin!=='tab')bc?.postMessage({kind:'update',update:u});});if('BroadcastChannel'in window){bc=new BroadcastChannel('peerbench:'+id);bc.onmessage=e=>{if(e.data.kind==='hello')bc.postMessage({kind:'update',update:Y.encodeStateAsUpdate(doc)});if(e.data.kind==='update')Y.applyUpdate(doc,new Uint8Array(e.data.update),'tab');};bc.postMessage({kind:'hello'});}localStorage.setItem('peerbench-last',id);$('#welcome').hidden=true;$('#room-workspace').hidden=false;$$('.room-only').forEach(e=>e.hidden=false);renderRooms();setView('board');status('saved');renderRoom();if(room.autoConnect&&!room.archived&&room.server)await connect();if(innerWidth<760){prefs.nav=false;applyPrefs();}}
async function newRoom(name,sample=false,fromDoc=null){const id=uid();const r={id,key:randomKey(),name:name||'Untitled room',server:config.signalingUrl||new URL('connect',location.href.split('#')[0]).href.replace(/^http/,'ws'),persist:config.persistByDefault!==false,autoConnect:false,created:Date.now()};const d=fromDoc||new Y.Doc();if(!fromDoc)seed(d,r.name,sample);else{d.getMap('meta').set('name',r.name);for(const [fid,f]of d.getMap('files'))if(f.hosted)d.getMap('files').set(fid,{...f,hosted:false});}await S.storeFull(id,d);d.destroy();await S.putRoom(r);rooms.push(r);await openRoom(id);return r;}
function createDialog(sample=false){modal('Make room for an idea',`<p>A room brings your board, notes, files, and conversation together. Start here, then invite your people.</p><form id="create-room-form"><label class="field">Room name<input id="new-room-name" placeholder="Community build, studio plans…" maxlength="100" required autofocus></label><label class="checkbox-row"><input id="room-sample" type="checkbox" ${sample?'checked':''}> Add a small sample project to explore</label><div class="dialog-actions"><button class="primary">Create room</button></div></form>`);$('#new-room-name').focus();$('#create-room-form').onsubmit=action(async e=>{e.preventDefault();const name=$('#new-room-name').value.trim();if(!name)return;const sample=$('#room-sample').checked;closeModal();await newRoom(name,sample);toast('Room created. Your work saves on this device.');});}
function setView(next){if(next!=='notes'){rich?.destroy();rich=null;$('#note-editor-wrap').dataset.note='';awareness?.setLocalStateField('cursor',null);}view=next;$$('[data-view]').forEach(b=>{if(b.dataset.view===view)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});for(const v of ['board','notes','drawing','files'])$('#'+v+'-view').hidden=v!==view;net?.presence(prefs.name,view);renderRoom();}
function renderRoom(){if(!doc)return;const name=String(doc.getMap('meta').get('name')||room.name);$('#room-title').textContent=name;$('#room-breadcrumb').textContent=name;document.title=name+' · PEERBENCH';if(room.name!==name){room.name=name;S.putRoom(room).catch(error);renderRooms();}if(view==='board')renderBoard();if(view==='notes')renderNotes();if(view==='drawing'){if(!drawing)drawing=new Whiteboard($('#drawing-view'),doc,room,{toast,download,files:()=>setView('files')});drawing.render();}if(view==='files')renderFiles().catch(error);renderChat();renderStatus();}
function renderBoard(){const search=$('#task-search').value.toLowerCase(),priority=$('#priority-filter').value,sort=$('#task-sort').value;let rows=mapRows('tasks').map(([id,t])=>({id,...t.toJSON()}));const total=rows.length,done=rows.filter(t=>t.status==='done').length;rows=rows.filter(t=>(!priority||t.priority===priority)&&(!search||[t.title,t.description,t.assignee,t.tags].join(' ').toLowerCase().includes(search)));rows.sort((a,b)=>sort==='title'?String(a.title).localeCompare(String(b.title)):sort==='due'?(a.due||'9999').localeCompare(b.due||'9999'):sort==='newest'?b.created-a.created:a.created-b.created);$('#board').innerHTML=Object.entries(labels).map(([state,label])=>{const tasks=rows.filter(t=>(Object.hasOwn(labels,t.status)?t.status:'todo')===state);return `<section class="column" data-column="${state}" aria-label="${label}"><div class="column-header"><span class="status-dot ${state}"></span><h2>${label}</h2><span class="count">${tasks.length}</span><button class="icon-button" data-add="${state}" aria-label="Add task to ${label}">+</button></div>${tasks.map(t=>`<article class="task-card" tabindex="0" role="button" draggable="true" data-task="${t.id}" aria-label="Edit task: ${esc(t.title)}"><div class="card-top">${t.tags?`<span class="tag">${esc(String(t.tags).split(',')[0])}</span>`:''}<span class="priority ${t.priority==='high'?'high':''}">${t.priority==='high'?'↑ High':t.priority==='low'?'↓ Low':''}</span></div><h3>${esc(t.title)}</h3><div class="card-bottom"><span class="card-assignee"><span class="mini-avatar">${esc(t.assignee?String(t.assignee)[0].toUpperCase():'○')}</span><span>${esc(t.assignee||'Unassigned')}</span></span>${t.due?`<span class="due ${t.due<day()&&state!=='done'?'overdue':''}">${esc(t.due.slice(5))}</span>`:'<span>↗</span>'}</div></article>`).join('')||`<div class="column-empty">${search||priority?'No matching tasks.':state==='todo'?'What could we make next?':state==='doing'?'Give an idea some momentum.':'A little progress belongs here.'}</div>`}<button class="column-add" data-add="${state}">+ Add a task</button></section>`;}).join('');$$('[data-task]').forEach(el=>{el.onclick=()=>taskDialog(el.dataset.task);el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();taskDialog(el.dataset.task);}};el.ondragstart=e=>{e.dataTransfer.setData('text/peerbench-task',el.dataset.task);e.dataTransfer.effectAllowed='move';};});$$('[data-add]').forEach(b=>b.onclick=()=>taskDialog(null,b.dataset.add));$$('[data-column]').forEach(c=>{c.ondragover=e=>{if(e.dataTransfer.types.includes('text/peerbench-task')){e.preventDefault();c.classList.add('drag-over');}};c.ondragleave=()=>c.classList.remove('drag-over');c.ondrop=e=>{e.preventDefault();c.classList.remove('drag-over');const t=doc.getMap('tasks').get(e.dataTransfer.getData('text/peerbench-task'));if(t)H.changeFields(doc,'tasks',e.dataTransfer.getData('text/peerbench-task'),{status:c.dataset.column},prefs.name);};});$('#board-summary').innerHTML=`<span>${done} of ${total} made</span><div class="progress-track" aria-hidden="true"><span style="width:${total?done/total*100:0}%"></span></div><span>${total?Math.round(done/total*100):0}%</span>`;}
function taskDialog(id,state='todo'){const t=id?doc.getMap('tasks').get(id):null;const basis=t?Object.fromEntries(['title','description','status','priority','assignee','due','tags'].map(k=>[k,H.heads(doc,'tasks',id,k).map(r=>r.id)])):null;const x=t?.toJSON()||{title:'',description:'',status:state,priority:'normal',assignee:'',due:'',tags:''};modal(id?'Shape this task':'Something to make',`<form id="task-form"><label class="field">Task<input id="task-title" value="${esc(x.title)}" placeholder="What needs doing?" maxlength="300" required></label><label class="field">Notes<textarea id="task-description" rows="4" maxlength="10000" placeholder="A little context goes a long way.">${esc(x.description)}</textarea></label><div class="field-grid"><label class="field">Stage<select id="task-status">${Object.entries(labels).map(([v,l])=>`<option value="${v}" ${x.status===v?'selected':''}>${l}</option>`).join('')}</select></label><label class="field">Priority<select id="task-priority">${['low','normal','high'].map(v=>`<option ${x.priority===v?'selected':''}>${v}</option>`).join('')}</select></label><label class="field">Person<input id="task-assignee" maxlength="60" value="${esc(x.assignee)}" placeholder="Anyone / a name"></label><label class="field">Due date<input id="task-due" type="date" value="${esc(x.due)}"></label></div><label class="field">Labels <input id="task-tags" value="${esc(x.tags)}" maxlength="200" placeholder="materials, experiment, next week"></label><div class="dialog-actions">${id?'<button type="button" class="text-button danger" id="delete-task">Move to trash</button><button type="button" class="secondary" id="duplicate-task">Duplicate</button>':''}<button class="primary">${id?'Save changes':'Add task'}</button></div></form>`);$('#task-title').focus();$('#task-form').onsubmit=action(e=>{e.preventDefault();const fields=Object.fromEntries(['title','description','status','priority','assignee','due','tags'].map(k=>[k,$('#task-'+k).value.trim()]));if(!fields.title)return;if(id){H.changeFields(doc,'tasks',id,Object.fromEntries(Object.entries(fields).filter(([k,v])=>v!==x[k])),prefs.name,'Edit',basis);}else addTask(doc,fields);closeModal();});if(id){$('#delete-task').onclick=()=>{H.changeFields(doc,'tasks',id,{deleted:true},prefs.name,'Moved to trash');closeModal();toast('Task moved to trash. Restore it in Snapshots & trash.');};$('#duplicate-task').onclick=()=>{addTask(doc,{...x,title:x.title+' (copy)',created:Date.now()});closeModal();toast('Task duplicated.');};}}
function renderNotes(){const rows=mapRows('notes');if(!rows.some(([id])=>id===noteId))noteId=rows[0]?.[0]||null;$('#note-list').innerHTML=rows.map(([id,n])=>`<button class="note-link ${id===noteId?'active':''}" data-note="${id}">${esc(n.get('title'))}</button>`).join('');$$('#note-list [data-note]').forEach(b=>b.onclick=()=>{noteId=b.dataset.note;renderNotes();});if(!noteId){rich?.destroy();rich=null;undo?.destroy();undo=null;$('#note-editor-wrap').innerHTML='<div class="empty"><h2>A place to think out loud.</h2><p>Add a note to start writing together.</p><button class="secondary" id="add-note-empty">+ New note</button></div>';$('#add-note-empty').onclick=createNote;return;}const n=doc.getMap('notes').get(noteId);const t=n.get('body');if(!(t instanceof Y.Text))return;if($('#note-editor-wrap').dataset.note!==noteId||$('#note-editor-wrap').dataset.mode!==noteMode||!$('#note-body')){rich?.destroy();rich=null;undo?.destroy();$('#note-editor-wrap').dataset.mode=noteMode;undo=new Y.UndoManager(t,{trackedOrigins:new Set(['ui'])});$('#note-editor-wrap').dataset.note=noteId;$('#note-editor-wrap').innerHTML=`<div class="note-editor-header"><input class="note-title" id="note-title" aria-label="Note title" maxlength="150"><button id="save-note-revision" class="secondary small" title="Save this text in shared revision history">Save revision</button><button id="note-revisions" class="icon-button" aria-label="Note history">◷</button><button id="undo-note" class="icon-button" aria-label="Undo your last change" title="Undo your last change">↶</button><button id="export-note" class="icon-button" aria-label="Export note" title="Export Markdown or formatted HTML">↓</button><button id="delete-note" class="icon-button" aria-label="Move note to trash" title="Move note to trash">×</button></div><div class="notebook-tools"><button data-note-mode="write" class="secondary small">Text</button><button data-note-mode="preview" class="secondary small">Preview</button><button data-note-mode="format" class="secondary small">Format</button><button id="link-material" class="text-button">Link a material</button></div><div id="note-preview" class="note-preview" hidden></div><div id="rich-note" hidden></div><textarea id="note-body" class="note-body" aria-label="Shared note" placeholder="Put an idea on the page. Markdown welcome." spellcheck="true"></textarea><div class="note-caption" id="note-caption"></div>`;$$('[data-note-mode]').forEach(b=>{b.setAttribute('aria-pressed',String(b.dataset.noteMode===noteMode));b.onclick=()=>{noteMode=b.dataset.noteMode;renderNotes();};});$('#link-material').onclick=linkMaterial;$('#note-body').hidden=noteMode!=='write';$('#note-preview').hidden=noteMode!=='preview';$('#rich-note').hidden=noteMode!=='format';if(noteMode==='format')rich=richEditor($('#rich-note'),t,awareness);$('#save-note-revision').onclick=()=>{H.saveNoteRevision(doc,noteId,prefs.name);toast('Revision saved in shared history.');};$('#note-revisions').onclick=()=>revisionDialog('notes',noteId);$('#note-title').oninput=()=>doc.transact(()=>n.set('title',$('#note-title').value),'ui');$('#note-body').oninput=()=>editText(t,$('#note-body').value);$('#note-body').onkeydown=e=>{if((e.ctrlKey||e.metaKey)&&e.key==='z'){e.preventDefault();e.shiftKey?undo.redo():undo.undo();renderNotes();}};$('#undo-note').onclick=()=>{(rich?.undo||undo).undo();renderNotes();};$('#export-note').onclick=()=>{if(t.toDelta().some(d=>d.attributes))download(safeName(n.get('title'))+'.html','<!doctype html><meta charset="utf-8"><title>'+esc(n.get('title'))+'</title>'+noteHTML(t),'text/html');else download(safeName(n.get('title'))+'.md',t.toString(),'text/markdown');};$('#delete-note').onclick=()=>{doc.transact(()=>n.set('deleted',true),'ui');noteId=null;toast('Note moved to trash.');};}const body=$('#note-body');if(document.activeElement!==$('#note-title'))$('#note-title').value=String(n.get('title')||'');if(body.value!==t.toString()){const start=body.selectionStart,end=body.selectionEnd;body.value=t.toString();if(document.activeElement===body){const a=lastNoteCaret?Y.createAbsolutePositionFromRelativePosition(lastNoteCaret.a,doc)?.index:start,b=lastNoteCaret?Y.createAbsolutePositionFromRelativePosition(lastNoteCaret.b,doc)?.index:end;body.setSelectionRange(a??start,b??end);}}lastNoteCaret=null;if(noteMode==='preview')$('#note-preview').innerHTML=noteHTML(t);$('#note-caption').textContent=`${t.length.toLocaleString()} characters · Text, Markdown preview & shared formatting · Changes merge automatically`;}

function linkMaterial(){const items=[];for(const kind of ['tasks','notes','files'])for(const [id,item]of mapRows(kind))items.push({id,kind,title:kind==='files'?item.name:item.get('title')});modal('Link a room material',`<p>Choose a task, note, or attachment in this room.</p><label class="field">Material<select id="material-choice">${items.map((x,i)=>`<option value="${i}">${esc(x.kind)} · ${esc(x.title)}</option>`).join('')}</select></label><button id="insert-material" class="primary" ${items.length?'':'disabled'}>Insert link</button>`);$('#insert-material').onclick=()=>{const x=items[Number($('#material-choice').value)],href='#material='+x.kind+':'+x.id,n=doc.getMap('notes').get(noteId),t=n.get('body');if(rich){const range=rich.quill.getSelection()||{index:t.length};rich.quill.insertText(range.index,x.title,{link:href},'user');}else{const body=$('#note-body'),at=body.selectionStart;doc.transact(()=>t.insert(at,`[${String(x.title).replaceAll(']','')}]( ${href} )`.replace('( ','(').replace(' )',')')),'ui');}closeModal();toast('Material linked. Open it from Preview or a formatted link.');};}
$('#note-editor-wrap').addEventListener('click',action(async e=>{const a=e.target.closest('a');if(!a)return;const hash=new URL(a.href,location.href).hash;if(!hash.startsWith('#material='))return;e.preventDefault();const [kind,id]=hash.slice(10).split(':');if(!['tasks','notes','files'].includes(kind))throw Error('Unknown room material type.');const item=doc.getMap(kind).get(id);if(!item||(kind==='files'?item.deleted:item.get('deleted')))throw Error('This material is missing or in the trash.');if(kind==='tasks')taskDialog(id);if(kind==='notes'){noteId=id;renderNotes();}if(kind==='files')setView('files');}));

function createNote(){noteId=addNote(doc,'Untitled note');setView('notes');$('#note-title')?.focus();$('#note-title')?.select();}
let chatSignature='';
function renderChat(){const rows=mapRows('messages').sort((a,b)=>(a[1].time-b[1].time)||a[0].localeCompare(b[0]));$('#chat-count').textContent=rows.length;const sig=room.id+':'+rows.map(([id,m])=>id+':'+m.text).join('|');if(sig===chatSignature)return;chatSignature=sig;const pane=$('#chat-messages'),bottom=pane.scrollHeight-pane.scrollTop-pane.clientHeight<80;pane.innerHTML=rows.map(([id,m])=>`<div class="chat-message"><div class="message-header"><span class="mini-avatar">${esc(String(m.name||'M')[0].toUpperCase())}</span><strong>${esc(m.name||'Maker')}</strong><time title="${esc(new Date(m.time).toLocaleString())}">${esc(new Date(m.time).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}))}</time></div><div class="message-text">${esc(m.text)}</div></div>`).join('')||'<div class="chat-empty"><span class="chat-symbol">☏</span>A good project starts<br>with a conversation.<br><br>Leave a thought for your people.</div>';if(bottom)pane.scrollTop=pane.scrollHeight;}
$('#chat-form').onsubmit=e=>{e.preventDefault();const text=$('#chat-input').value.trim();if(!text||!doc)return;doc.getMap('messages').set(uid(),{text,name:prefs.name,time:Date.now()});$('#chat-input').value='';queueMicrotask(()=>$('#chat-messages').scrollTop=$('#chat-messages').scrollHeight);};$('#chat-input').onkeydown=e=>{if(e.key==='Enter'&&(e.ctrlKey||e.metaKey)){$('#chat-form').requestSubmit();}};
function renderStatus(){if(!room)return;const direct=net?[...net.peers.values()].filter(p=>p.dc?.readyState==='open').length:0,members=net?.members.size||0;const connected=net?.ready;$('#connection-status').textContent=direct?`↔ ${direct} peer${direct===1?'':'s'} connected`:connected?'◎ Server connected':net?.state==='connecting'?'◌ Connecting…':'○ Local only';$('#connection-status').classList.toggle('online',direct>0||connected);$('#people-status').textContent=members?`${members+1} at the bench`:'';$('#sync-detail').textContent=net?.error||[direct?`${direct} WebRTC connection${direct===1?'':'s'}`:connected?'Encrypted relay available':'Changes stay on this device until you connect.',net?.serverSaved?'Encrypted server copy saved':connected&&room.persist?'Saving encrypted server copy…':'',net?.lastAck?'Peer receipt confirmed':''].filter(Boolean).join(' · ');if($('#live-connections'))renderConnectionList();const conflictCount=H.conflicts(doc).length;$('#history').textContent=conflictCount?`History · ${conflictCount} conflict${conflictCount===1?'':'s'}`:'History & recovery';}
async function connect(){if(!room.server)throw Error('Enter your connection server first.');const u=new URL(room.server);if(!['ws:','wss:'].includes(u.protocol))throw Error('Use a ws:// or wss:// server URL.');if(location.protocol==='https:'&&u.protocol!=='wss:')throw Error('An HTTPS app needs a secure wss:// connection server.');net?.destroy();net=new Collaboration(room,doc,{name:prefs.name,view,awareness,iceServers:room.iceServers||config.iceServers||[]});net.addEventListener('status',renderStatus);net.addEventListener('file',e=>transfers.handle(e.detail).catch(error));await net.start();renderStatus();}
function currentInvite(){const u=new URL(location.href);u.hash=new URLSearchParams({room:room.id,key:room.key,server:room.server,store:room.persist?'1':'0'}).toString();return u.href;}
function connectionDialog(){modal('Bring your people together',`<p>Anyone with the invitation can read, edit, and invite others. Share it privately with people you trust.</p><label class="field">Private invitation<textarea id="invite-url" class="invite-url" readonly>${esc(currentInvite())}</textarea></label><button id="copy-invite" class="primary">Copy invitation</button><div class="callout"><strong>Keep this room available.</strong> Leave a device connected, or enable the encrypted server copy below so people can catch up later. Files need a connected holder, or an encrypted attachment copy on a server with hosting enabled.</div><div id="live-connections"></div><button id="download-diagnostics" class="text-button">Download connection diagnostics</button><form id="connection-form"><details ${prefs.advanced||!net?.ready?'open':''}><summary>Connection settings</summary><div><label class="field">Connection server<input id="server-url" value="${esc(room.server)}" placeholder="wss://your-server.example/connect" required><small>Use the companion PEERBENCH server. A static file host alone cannot provide this service.</small></label><label class="checkbox-row"><input type="checkbox" id="persist-server" ${room.persist?'checked':''}> Keep an encrypted copy of notes, boards, and conversation on this server</label><label class="checkbox-row"><input type="checkbox" id="auto-connect" ${room.autoConnect?'checked':''}> Reconnect automatically when I open this room</label><details ${prefs.advanced?'open':''}><summary>Advanced: STUN / TURN servers</summary><label class="field">ICE server configuration (JSON)<textarea id="ice-servers" rows="4" spellcheck="false">${esc(JSON.stringify(room.iceServers||config.iceServers||[],null,2))}</textarea><small>No public service is contacted by default. TURN credentials saved here stay on this browser and are not included in invitations. Prefer short-lived credentials.</small></label></details></div></details><div class="dialog-actions"><button id="disconnect" type="button" class="secondary">Disconnect</button><button class="primary">Save & connect</button></div></form>`);renderConnectionList();$('#download-diagnostics').onclick=()=>download('peerbench-diagnostics.json',JSON.stringify(net?.diagnostics()||{connected:false,secureContext:isSecureContext},null,2));$('#copy-invite').onclick=action(async()=>{try{await navigator.clipboard.writeText(currentInvite());toast('Invitation copied. Share it privately.');}catch{$('#invite-url').select();toast('Select and copy the invitation above.');}});$('#disconnect').onclick=async()=>{room.autoConnect=false;await S.putRoom(room);net?.destroy();net=null;renderStatus();closeModal();toast('Disconnected. You can keep working locally.');};$('#connection-form').onsubmit=action(async e=>{e.preventDefault();const server=$('#server-url').value.trim();const u=new URL(server);if(!['ws:','wss:'].includes(u.protocol)||u.username||u.password)throw Error('Use a ws:// or wss:// connection server URL.');let ice;try{ice=JSON.parse($('#ice-servers').value);}catch{throw Error('ICE servers must be valid JSON.');}if(!Array.isArray(ice)||ice.some(x=>!x||!x.urls||!['string','object'].includes(typeof x.urls)))throw Error('ICE servers must be an array of objects with urls.');room.server=server;room.persist=$('#persist-server').checked;room.autoConnect=$('#auto-connect').checked;room.iceServers=ice;await S.putRoom(room);await connect();$('#invite-url').value=currentInvite();toast('Connection settings saved.');});}
function renderConnectionList(){if(!$('#live-connections'))return;$('#live-connections').innerHTML=net?`<ul class="detail-list"><li><span>${net.ready?'Server connected':net.state==='connecting'?'Connecting to server…':'Server disconnected'}</span><span>${net.serverSaved?'Archive saved':''}</span></li>${[...net.peers.values()].map(p=>`<li><span>${esc(p.name)}<small>${esc(p.view||'In this room')}</small></span><span>${p.dc?.readyState==='open'?p.route==='TURN'?'WebRTC via TURN':'WebRTC connected':'Server relay / connecting'}</span></li>`).join('')}</ul>${net.archive?`<p class="muted">Archive: ${fmt(net.archive.bytes)} / ${fmt(net.archive.limit)} · ${net.archive.updates} records${net.latency!==undefined?` · ${net.latency} ms round trip`:''}</p>`:''}${net.error?`<p class="error-message">${esc(net.error)}</p>`:''}`:'<p class="muted">Not connected. Your work is saved on this device.</p>';}
function joinDialog(link=''){modal('Join a shared room',`<p>Paste the private invitation you received. Joining shares your display name and connects to the server named in the invitation.</p><form id="join-form"><label class="field">Invitation<textarea id="join-link" rows="4" required placeholder="https://…/#room=…&key=…">${esc(link)}</textarea></label><label class="field">Your display name<input id="join-name" maxlength="60" value="${esc(prefs.name)}" required></label><div class="dialog-actions"><button class="primary">Join room</button></div></form>`);$('#join-form').onsubmit=action(async e=>{e.preventDefault();const r=inviteParse($('#join-link').value.trim());prefs.name=$('#join-name').value.trim()||'Maker';setPrefs();if(!r.server)r.server=config.signalingUrl||new URL('connect',location.href).href.replace(/^http/,'ws');const existing=rooms.find(x=>x.id===r.id);if(existing&&existing.key!==r.key)throw Error('This room is already saved with a different key. Check the invitation.');if(!existing){r.created=Date.now();r.autoConnect=true;await S.putRoom(r);rooms.push(r);}else{existing.server=r.server;existing.autoConnect=true;await S.putRoom(existing);}closeModal();history.replaceState(null,'',location.pathname+location.search);await openRoom(r.id);toast('Room opened. Connecting to your collaborators…');});}
async function addFiles(files){if(!room)return;await transfers.add(files);setView('files');toast('Files saved here. Peers can request them; archive hosting is optional.');}
async function renderFiles(){const serial=++fileRender,roomId=room.id;const rows=mapRows('files').sort((a,b)=>b[1].created-a[1].created);const local=await Promise.all(rows.map(async([id,f])=>({id,...f,local:!!await S.getAsset(roomId,id)})));if(room?.id!==roomId||view!=='files'||serial!==fileRender)return;
 const hosting=net?.ready&&net?.archive?.attachments?.enabled;const signature=JSON.stringify([roomId,!!hosting,!!net?.ready,local.map(f=>[f.id,f.name,f.local,f.hosted,f.by,f.size,transfers.states.get(f.id)?.status,transfers.states.get(f.id)?.error,transfers.states.get(f.id)?.direction])]);const progress=(f,t)=>`${t.status} · ${t.direction==='upload'?'upload':'download'} ${Math.round(t.offset/Math.max(1,f.size)*100)}%${t.error?' · '+t.error:''}`;const archiveLabel=()=>net?.archive?.attachments?`Encrypted attachment archive: ${fmt(net.archive.attachments.bytes)} / ${fmt(net.archive.attachments.limit)}${hosting?'':' · hosting disabled'}`:'Connect for archive availability';if(fileSignature===signature&&$('#queue-files')){for(const f of local){const t=transfers.states.get(f.id),el=document.querySelector('[data-transfer-status="'+CSS.escape(f.id)+'"]');if(el&&t)el.textContent=progress(f,t);}if($('#archive-file-usage'))$('#archive-file-usage').textContent=archiveLabel();return;}fileSignature=signature;
 $('#file-list').innerHTML=`<div class="transfer-toolbar"><button id="queue-files" class="secondary small">Get all missing files</button><button id="pause-files" class="text-button">Pause transfers</button><span class="muted" id="archive-file-usage">${net?.archive?.attachments?`Encrypted attachment archive: ${fmt(net.archive.attachments.bytes)} / ${fmt(net.archive.attachments.limit)}${hosting?'':' · hosting disabled'}`:'Connect for archive availability'}</span></div>`+ (local.map(f=>{const t=transfers.states.get(f.id),active=t&&['queued','receiving','uploading'].includes(t.status);return `<div class="file-row"><span class="file-icon">▧</span><div class="file-info"><strong>${esc(f.name)}</strong><small>${fmt(f.size)} · ${esc(f.by||'Maker')} · ${f.local?'On this device':f.hosted?'Encrypted archive copy available':'Available from a connected holder'}</small>${t?`<small class="transfer-state" data-transfer-status="${f.id}">${esc(t.status)} · ${t.direction==='upload'?'upload':'download'} ${Math.round(t.offset/Math.max(1,f.size)*100)}%${t.error?' · '+esc(t.error):''}</small>`:''}</div><div class="file-actions"><button class="secondary" data-file-action="${f.id}" ${active&&!f.local?'disabled':''}>${f.local?'↓ Download':active?'Queued / receiving':t?'Resume transfer':'Get from peers'}</button>${!f.local?`<button class="text-button" data-file-archive-get="${f.id}" ${!net?.ready||active?'disabled':''}>Get from archive</button>`:`<button class="text-button" data-file-host="${f.id}" ${!hosting||active?'disabled':''}>${f.hosted?'Refresh archive copy':'Archive encrypted copy'}</button>`}${t&&t.status!=='complete'?`${active?`<button class="text-button" data-file-pause="${f.id}">Pause</button>`:`<button class="text-button" data-file-retry="${f.id}">Retry</button>`}<button class="text-button" data-file-cancel="${f.id}">Cancel</button>`:''}${f.hosted?`<button class="text-button danger" data-file-unhost="${f.id}" ${!net?.ready?'disabled':''}>Remove archive copy</button>`:''}</div><button class="icon-button" data-file-delete="${f.id}" aria-label="Move ${esc(f.name)} to trash">×</button></div>`;}).join('')||'<div class="empty"><h2>Bring something to the bench.</h2><p>Share sketches, references, documents, or a photograph of what you made.</p></div>');
 $$('[data-file-action]').forEach(b=>b.onclick=action(async()=>{const id=b.dataset.fileAction,f=doc.getMap('files').get(id),blob=await S.getAsset(room.id,id);if(blob)download(f.name,blob);else await transfers.enqueue(id);}));
 for(const [attr,fn]of [['filePause',id=>transfers.pause(id)],['fileCancel',id=>transfers.cancel(id)],['fileRetry',id=>{const s=transfers.states.get(id);return transfers.enqueue(id,s?.direction,s?.source);}],['fileArchiveGet',id=>transfers.enqueue(id,'download','archive')],['fileHost',id=>transfers.enqueue(id,'upload','archive')]]){const selector=attr.replace(/[A-Z]/g,c=>'-'+c.toLowerCase());$$('[data-'+selector+']').forEach(b=>b.onclick=action(()=>fn(b.dataset[attr])));}
 $$('[data-file-unhost]').forEach(b=>b.onclick=action(async()=>{if(!confirm('Remove this encrypted server copy? Devices keep downloaded copies.'))return;const id=b.dataset.fileUnhost;await transfers.cancel(id);await net.request('asset-delete',{id});doc.getMap('files').set(id,{...doc.getMap('files').get(id),hosted:false});toast('Encrypted archive copy removed.');}));
 $$('[data-file-delete]').forEach(b=>b.onclick=action(async()=>{const id=b.dataset.fileDelete;await transfers.pause(id);doc.getMap('files').set(id,{...doc.getMap('files').get(id),deleted:true});toast('File moved to trash. Copies remain available for recovery.');}));$('#queue-files').onclick=action(async()=>{for(const f of local)if(!f.local)await transfers.enqueue(f.id,'download',f.hosted?'archive':'peers');});$('#pause-files').onclick=action(async()=>{for(const id of transfers.states.keys())await transfers.pause(id);});
}
async function exportBackup(){if(!room)return;toast('Preparing your complete backup…');const data=await S.backup(room,doc);download(safeName(room.name)+'-peerbench.json',JSON.stringify(data,null,2));toast('Backup exported. It includes files stored on this device.');}
async function importBackup(file){if(file.size>400*1024*1024)throw Error('Backup exceeds the 400 MiB import limit.');let data;try{data=JSON.parse(await file.text());}catch{throw Error('This file is not valid JSON.');}const d=validateBackup(data);const assets=[];for(const a of data.assets||[]){if(typeof a.id!=='string'||a.id.length>40||typeof a.data!=='string'||a.data.length>70e6){d.destroy();throw Error('An attachment in the backup is invalid.');}const meta=d.getMap('files').get(a.id);const bytes=unb64(a.data);if(!meta||meta.size!==bytes.length||await sha(bytes)!==meta.hash){d.destroy();throw Error('An attachment failed its integrity check.');}assets.push({id:a.id,blob:new Blob([bytes],{type:meta.type})});}const r=await newRoom(String(data.name||'Imported room').slice(0,100)+' (restored)',false,d);for(const a of assets)await S.putAsset(r.id,a.id,a.blob);toast('Backup restored as a separate local room. Your other rooms are unchanged.');}
async function recoveryDialog(){const snaps=await S.snapshots(room.id);const trash=[];for(const kind of ['tasks','notes','files'])for(const [id,x]of doc.getMap(kind)){if(kind==='files'?x.deleted:x.get?.('deleted'))trash.push({kind,id,name:kind==='files'?x.name:x.get('title')});}modal('Snapshots & trash',`<p>Snapshots capture this room’s shared records. Restoring opens a separate local room, preserving ongoing collaboration. File bytes remain in local storage; use Backup for a portable copy.</p><button id="shared-revisions" class="secondary">Shared history & conflicts</button> <button id="storage-room" class="secondary">Storage & archive</button><br><br><button id="make-snapshot" class="primary">+ Save a snapshot</button><div class="recovery-section"><h3>Saved snapshots</h3>${snaps.map(s=>`<div class="recovery-row"><span>${esc(s.name)}<small>${esc(new Date(s.created).toLocaleString())}</small></span><button class="secondary small" data-restore-snapshot="${s.id}">Restore as new room</button><button class="icon-button danger" data-delete-snapshot="${s.id}" aria-label="Delete snapshot">×</button></div>`).join('')||'<p>No snapshots yet. Save one before a big change.</p>'}</div><div class="recovery-section"><h3>Trash</h3>${trash.map(t=>`<div class="recovery-row"><span>${esc(t.name)}<small>${esc(t.kind)}</small></span><button class="secondary small" data-restore-kind="${t.kind}" data-restore-item="${t.id}">Restore</button></div>`).join('')||'<p>Nothing in the trash.</p>'}</div>`);$('#shared-revisions').onclick=()=>revisionDialog();$('#storage-room').onclick=action(storageDialog);$('#make-snapshot').onclick=action(async()=>{await S.makeSnapshot(room,doc,new Date().toLocaleString());await recoveryDialog();toast('Snapshot saved on this device.');});$$('[data-restore-item]').forEach(b=>b.onclick=action(async()=>{const m=doc.getMap(b.dataset.restoreKind),id=b.dataset.restoreItem;doc.transact(()=>{if(b.dataset.restoreKind==='files')m.set(id,{...m.get(id),deleted:false});else m.get(id).set('deleted',false);},'ui');await recoveryDialog();toast('Restored to the room.');}));$$('[data-restore-snapshot]').forEach(b=>b.onclick=action(async()=>{const snap=snaps.find(s=>s.id===b.dataset.restoreSnapshot),oldRoom=room.id,d=new Y.Doc();Y.applyUpdate(d,unb64(snap.update));const ids=[...d.getMap('files').keys()];closeModal();const r=await newRoom(room.name+' (snapshot)',false,d);for(const fid of ids){const a=await S.getAsset(oldRoom,fid);if(a)await S.putAsset(r.id,fid,a);}toast('Snapshot opened as a separate room.');}));$$('[data-delete-snapshot]').forEach(b=>b.onclick=action(async()=>{if(!confirm('Delete this local snapshot?'))return;await S.deleteSnapshot(b.dataset.deleteSnapshot);await recoveryDialog();}));}

function revisionDialog(kind,target){
 const rows=H.revisions(doc,kind,target),issues=H.conflicts(doc).filter(r=>!target||r.target===target);
 modal('Shared history & conflicts',`<p>Task fields are recorded when edited. Save notebook revisions before important changes. Display names are self-selected; this is a working history, not a verified audit trail.</p>${issues.length?'<h3>Choose a value to resolve</h3>':''}${issues.map(r=>`<div class="revision-conflict"><strong>${esc(doc.getMap(r.kind).get(r.target)?.get('title'))} · ${esc(r.field)}</strong>${r.choices.map(c=>`<div class="recovery-row"><span><b>${esc(c.after)}</b><small>${esc(c.actor)}</small></span><button class="secondary small" data-resolve="${c.id}">Use this value</button></div>`).join('')}</div>`).join('')}<h3>${rows.length} revisions</h3>${rows.slice(0,100).map(r=>`<div class="recovery-row"><span><b>${esc(doc.getMap(r.kind).get(r.target)?.get('title')||'Record')} · ${esc(r.field)}</b><small>${esc(r.actor)} · ${esc(r.label)} · ${esc(new Date(r.time).toLocaleString())}</small></span><button class="secondary small" data-compare="${r.id}">Compare</button></div>`).join('')||'<p>No revisions yet. Edit a task or save a notebook revision.</p>'}${rows.length>100?'<p>Showing the newest 100. All revisions remain in backups.</p>':''}`);
 $$('[data-resolve]').forEach(b=>b.onclick=()=>{const r=H.revisions(doc).find(r=>r.id===b.dataset.resolve);H.changeFields(doc,r.kind,r.target,{[r.field]:r.after},prefs.name,'Resolved conflict');revisionDialog(kind,target);toast('Conflict resolved. Both earlier choices remain in history.');});
 $$('[data-compare]').forEach(b=>b.onclick=()=>{const r=rows.find(r=>r.id===b.dataset.compare),current=doc.getMap(r.kind).get(r.target)?.get(r.field);modal('Compare revision',`<p>${esc(r.field)} · ${esc(r.actor)} · ${esc(new Date(r.time).toLocaleString())}</p><div class="revision-compare"><section><h3>Saved value</h3><pre>${esc(r.after)}</pre></section><section><h3>Current value</h3><pre>${esc(current?.toString?.()??current)}</pre></section></div><p>Restore changes only this ${r.kind==='notes'?'note’s text':'field'} in the live room. Earlier values remain in history.</p><div class="dialog-actions"><button id="revision-back" class="secondary">Back</button><button id="restore-revision" class="primary">Restore this value</button></div>`);$('#revision-back').onclick=()=>revisionDialog(kind,target);$('#restore-revision').onclick=()=>{H.restoreRevision(doc,r,prefs.name);revisionDialog(kind,target);toast('Selected value restored.');};});
}
async function storageDialog(){
 await save.settled();const usage=await S.roomUsage(room.id),estimate=await navigator.storage?.estimate?.();net?.socket({t:'archive-status'});
 modal('Storage & archive',`<p>Local records: <strong>${fmt(usage.recordBytes)}</strong> in ${usage.updates} saved updates. Files: <strong>${fmt(usage.assets)}</strong> (${fmt(usage.partials)} partial).</p><p class="muted">Browser origin storage: ${fmt(estimate?.usage||0)} / ${fmt(estimate?.quota||0)}. This includes other rooms.</p><div id="live-connections"></div><div class="stack"><button class="menu-item" id="compact-local">Compact local records<small>Atomically merge stored updates. All room content and history are retained.</small></button><button class="menu-item" id="compact-server" ${!net?.ready||net?.protocol<2?'disabled':''}>Compact encrypted server archive<small>Replay, encrypt a checkpoint, then replace covered records atomically.</small></button><button class="menu-item" id="clear-partials">Clear interrupted file downloads<small>Discard partial bytes on this device; completed files are kept.</small></button><button class="menu-item" id="archive-local">${room.archived?'Reopen this room':'Archive this room on this device'}<small>Keep records and files; stop automatic connections.</small></button><button class="menu-item" id="storage-backup">Export complete backup</button></div><p>Interrupted compaction keeps the previous archive. A backup is the portable recovery copy; browser storage can be cleared. Removing this device’s room never removes other people’s copies.</p>`);renderConnectionList();
 $('#compact-local').onclick=action(async()=>{await save.settled();await S.compactLocal(room.id);await storageDialog();toast('Local records compacted.');});
 $('#compact-server').onclick=action(async()=>{const b=$('#compact-server');b.disabled=true;b.textContent='Creating encrypted checkpoint…';try{await net.checkpoint();await storageDialog();toast('Encrypted checkpoint committed.');}catch(e){b.disabled=false;b.textContent='Retry encrypted checkpoint';throw e;}});
 $('#clear-partials').onclick=action(async()=>{await transfers.clearAll();await storageDialog();toast('Partial downloads cleared. You can request them again.');});
 $('#archive-local').onclick=action(async()=>{room.archived=!room.archived;if(room.archived){room.autoConnect=false;net?.destroy();net=null;}await S.putRoom(room);renderRooms();renderStatus();await storageDialog();});$('#storage-backup').onclick=action(exportBackup);
}

function renameDialog(){modal('Name this room',`<form id="rename-form"><label class="field">Room name<input id="rename-input" value="${esc(room.name)}" maxlength="100" required autofocus></label><div class="dialog-actions"><button class="primary">Save name</button></div></form>`);$('#rename-input').focus();$('#rename-input').select();$('#rename-form').onsubmit=e=>{e.preventDefault();const name=$('#rename-input').value.trim();if(!name)return;doc.transact(()=>doc.getMap('meta').set('name',name),'ui');closeModal();};}
async function printReport(){const data=roomData(doc);let drawingReport='';if(doc.getMap('drawing').size){if(!drawing)drawing=new Whiteboard($('#drawing-view'),doc,room,{toast,download,files:()=>setView('files')});drawingReport=(await drawing.document(false)).svg;}$('#print-report').innerHTML=`<div class="report-title"><div class="report-meta">PEERBENCH · PROJECT RECORD · v${VERSION}</div><h1>${esc(room.name)}</h1><div class="report-meta">Prepared ${esc(new Date().toLocaleString())} by ${esc(prefs.name)} · Local snapshot of this room</div></div><h2>Work board</h2><table><thead><tr><th>Task</th><th>Stage</th><th>Person</th><th>Priority / due</th></tr></thead><tbody>${Object.values(data.tasks).filter(t=>!t.deleted).map(t=>`<tr><td><strong>${esc(t.title)}</strong><br>${esc(t.description)}</td><td>${esc(labels[t.status]||t.status)}</td><td>${esc(t.assignee||'Unassigned')}</td><td>${esc(t.priority)}<br>${esc(t.due||'')}</td></tr>`).join('')}</tbody></table><h2>Notebook</h2>${Object.entries(data.notes).filter(([,n])=>!n.deleted).map(([nid,n])=>`<article><h3>${esc(n.title)}</h3>${noteHTML(doc.getMap('notes').get(nid)?.get('body')||{toDelta:()=>[],toString:()=>n.body})}</article>`).join('')||'<p>No notes.</p>'}<h2>Files</h2><table><thead><tr><th>Name</th><th>Size</th><th>Added by</th></tr></thead><tbody>${Object.values(data.files).filter(f=>!f.deleted).map(f=>`<tr><td>${esc(f.name)}</td><td>${fmt(f.size)}</td><td>${esc(f.by)}</td></tr>`).join('')}</tbody></table><h2>Whiteboard</h2>${drawingReport||'<p>No drawing yet.</p>'}<h2>Conversation</h2>${Object.values(data.messages).filter(m=>!m.deleted).sort((a,b)=>a.time-b.time).map(m=>`<article><strong>${esc(m.name)}</strong> <span class="report-meta">${esc(new Date(m.time).toLocaleString())}</span><pre>${esc(m.text)}</pre></article>`).join('')||'<p>No messages.</p>'}<p class="report-meta">All room members can edit shared records. Display names are self-selected. This report is not an authenticated audit trail.</p>`;closeModal();window.print();}
function roomMenu(){modal('Your room, your data',`<div class="stack"><button class="menu-item" id="menu-rename">Rename room</button><button class="menu-item" id="menu-export">Export complete backup<small>JSON records and files held on this device. Invitation keys are excluded.</small></button><button class="menu-item" id="menu-import">Restore a backup<small>Always opens a separate local room.</small></button><button class="menu-item" id="menu-print">Print / save PDF report<small>A clean project record of tasks, notes, files, and conversation.</small></button><button class="menu-item" id="menu-history">History, snapshots & trash</button><button class="menu-item" id="menu-storage">Storage & archive<small>Usage, compact records, and archive this room locally.</small></button><button class="menu-item" id="menu-new">Fresh start<small>Create an empty room. Keep this room intact.</small></button><button class="menu-item danger" id="menu-forget">Remove room from this device<small>Does not erase peers’ copies or the encrypted server archive.</small></button></div>`);$('#menu-rename').onclick=renameDialog;$('#menu-export').onclick=action(async()=>{closeModal();await exportBackup();});$('#menu-import').onclick=()=>$('#import-input').click();$('#menu-print').onclick=action(printReport);$('#menu-history').onclick=action(recoveryDialog);$('#menu-storage').onclick=action(storageDialog);$('#menu-new').onclick=()=>createDialog();$('#menu-forget').onclick=action(async()=>{if(!confirm('Remove this room, its local files, and snapshots from this device? Export a backup first if you need a copy.'))return;const old=room.id;await save.settled();transfers?.destroy();transfers=null;drawing?.destroy();drawing=null;rich?.destroy();rich=null;awareness?.destroy();awareness=null;net?.destroy();net=null;save.destroy();save=null;bc?.close();bc=null;doc.destroy();doc=null;room=null;await S.removeRoom(old);rooms=rooms.filter(r=>r.id!==old);closeModal();if(rooms.length)await openRoom(rooms[0].id);else showWelcome();toast('Local copy removed. Collaborators keep their copies.');});}
function preferences(){modal('Make yourself at home',`<form id="prefs-form"><div class="field-grid"><label class="field">Your display name<input id="prefs-name" value="${esc(prefs.name)}" maxlength="60" required></label><label class="field">Appearance<select id="prefs-theme">${[['light','Warm light'],['dark','After hours'],['contrast','High contrast']].map(([v,l])=>`<option value="${v}" ${prefs.theme===v?'selected':''}>${l}</option>`).join('')}</select></label></div><label class="checkbox-row"><input id="prefs-advanced" type="checkbox" ${prefs.advanced?'checked':''}> Advanced mode: show connection and ICE settings up front</label><div class="dialog-actions"><button class="primary">Save preferences</button></div></form><details><summary>How PEERBENCH works</summary><p><strong>Create → invite → make → keep.</strong> Your board, notebook, conversation, and file metadata save in this browser. Notes use a CRDT to merge simultaneous edits. Single-value task fields converge to one value when changed concurrently.</p><p>Click a task to edit it or change its stage. You can also drag it between columns. The notebook offers Text, safe Markdown Preview, and Format with shared cursors. Export produces Markdown for plain notes or sanitized HTML for formatted notes. Save revision keeps a shared checkpoint of text and formatting.</p><p>Use Invite people to connect to your self-hosted server. No public signaling, STUN, TURN, analytics, or AI services are used by default. Files transfer only when requested. Optional encrypted attachment hosting must be enabled by the server operator; use Archive encrypted copy for each file.</p><p>The invitation grants full room access. Display names are not verified identities. Browser copies and exported backups are unencrypted; the server archive and network messages are encrypted by a room key. Server operators can still see connection metadata.</p><p>A static host serves the interface; the included Node server supplies collaboration. For reliable internet connections, configure STUN/TURN. Server relay works when direct connections cannot. Keep regular backups: browser data can be cleared or evicted.</p><p>Use your browser’s Print dialog to save a PDF report. Snapshots & trash offers recovery without overwriting live rooms.</p></details><button class="text-button" id="persist-storage">Ask browser to retain local storage</button><p class="muted" id="storage-answer"></p><button class="text-button" id="prefs-import">Restore a backup</button><p class="muted">PEERBENCH v1.2.0 · Green Shoe Garage<br>GNU GPL v3 · No telemetry · No AI</p>`);$('#prefs-form').onsubmit=action(async e=>{e.preventDefault();prefs.name=$('#prefs-name').value.trim()||'Maker';prefs.theme=$('#prefs-theme').value;prefs.advanced=$('#prefs-advanced').checked;setPrefs();await net?.presence(prefs.name,view);closeModal();toast('Preferences saved.');});$('#prefs-theme').onchange=()=>{document.documentElement.dataset.theme=$('#prefs-theme').value;};$('#persist-storage').onclick=action(async()=>{const ok=await navigator.storage?.persist?.();$('#storage-answer').textContent=ok?'Persistent storage granted. Keep backups as well.':'The browser did not grant persistent storage. Download regular backups.';});$('#prefs-import').onclick=()=>$('#import-input').click();}
function showWelcome(){room=null;$('#welcome').hidden=false;$('#room-workspace').hidden=true;$$('.room-only').forEach(e=>e.hidden=true);$('#room-breadcrumb').textContent='Welcome';$('#save-status').textContent='● Ready';document.title='PEERBENCH — Make together.';renderRooms();}
$('#close-nav').onclick=()=>{prefs.nav=false;setPrefs();};matchMedia('(max-width:760px)').addEventListener('change',e=>{if(e.matches)prefs.nav=false;applyPrefs();});
$('#new-room-small').onclick=()=>createDialog();$('#create-first').onclick=()=>createDialog();$('#try-sample').onclick=()=>createDialog(true);$('#join-room').onclick=()=>joinDialog();$('#profile').onclick=preferences;$('#toggle-nav').onclick=()=>{prefs.nav=!prefs.nav;setPrefs();};$('#toggle-chat').onclick=()=>{prefs.chat=!prefs.chat;setPrefs();};$('#backup').onclick=action(exportBackup);$('#room-menu').onclick=roomMenu;$('#rename-room').onclick=renameDialog;$('#invite').onclick=connectionDialog;$('#connection-status').onclick=connectionDialog;$('#history').onclick=action(recoveryDialog);$('#add-task').onclick=()=>taskDialog();$('#add-note').onclick=createNote;$('#add-file').onclick=()=>$('#file-input').click();$('#file-drop').onclick=()=>$('#file-input').click();$('#file-drop').onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();$('#file-input').click();}};$('#file-drop').ondragover=e=>{e.preventDefault();$('#file-drop').classList.add('drag-over');};$('#file-drop').ondragleave=()=>$('#file-drop').classList.remove('drag-over');$('#file-drop').ondrop=action(async e=>{e.preventDefault();$('#file-drop').classList.remove('drag-over');await addFiles([...e.dataTransfer.files]);});$('#file-input').onchange=action(async e=>{const files=[...e.target.files];e.target.value='';await addFiles(files);});$('#import-input').onchange=action(async e=>{const file=e.target.files[0];e.target.value='';if(file){closeModal();await importBackup(file);}});$$('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));for(const id of ['task-search','priority-filter','task-sort'])$('#'+id).addEventListener(id==='task-search'?'input':'change',()=>renderBoard());$('.brand').onclick=async e=>{e.preventDefault();if(save)await save.settled();if(!room)showWelcome();else setView('board');};
document.addEventListener('pointerup',()=>{if(innerWidth>1050&&prefs.chat){const width=Math.round($('#chat-pane').getBoundingClientRect().width);if(width>=230&&width<=450&&width!==prefs.chatWidth){prefs.chatWidth=width;localStorage.setItem('peerbench-prefs',JSON.stringify(prefs));}}});
window.addEventListener('beforeunload',e=>{if(save?.pending){e.preventDefault();e.returnValue='';}});document.addEventListener('visibilitychange',()=>{if(document.hidden)save?.flush();});window.addEventListener('offline',()=>{toast('You are offline. Keep working; your changes save on this device.');renderStatus();});window.addEventListener('online',()=>{toast('Network available. Active connections will retry automatically.');});$('#dialog').addEventListener('close',applyPrefs);
async function init(){applyPrefs();if(!window.isSecureContext||!crypto.subtle){modal('Open PEERBENCH securely','<p>Open the app at <strong>http://localhost:8787</strong> on this computer, or serve it over HTTPS. Secure browser features are needed for private rooms and local storage.</p>');return;}try{config=await fetch('./config.json').then(r=>r.ok?r.json():{});}catch{config={};}try{await S.database();rooms=await S.listRooms();const last=localStorage.getItem('peerbench-last');if(rooms.length)await openRoom(rooms.some(r=>r.id===last)?last:rooms[0].id);else showWelcome();if(location.hash.includes('room='))joinDialog(location.href);if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>toast('Offline caching is unavailable. Local data still saves in this browser.'));}catch(e){modal('Your browser could not open local storage',`<p>${esc(e.message)}</p><p>Allow site storage and reload. If you have a backup, keep it until local storage is available.</p>`);}}
init().catch(error);
